use glam::DVec3;use ingetrazo_core::dimensions::Dimension;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let cases:Vec<[[f64;3];3]>=serde_json::from_slice(&std::fs::read(dir.join("cases.json")).unwrap()).unwrap();let rows=cases.iter().map(|[a,b,p]|{let(o,axis)=Dimension::placement_for_cursor(DVec3::from_array(*a),DVec3::from_array(*b),DVec3::from_array(*p));serde_json::json!({"offset":o.to_array(),"axis":axis})}).collect::<Vec<_>>();std::fs::write(dir.join("placements.json"),serde_json::to_vec(&rows).unwrap()).unwrap();
 let mut scene=ingetrazo_formats::igz::load_igz(&dir.join("source.igz")).unwrap();let d=&mut scene.dimensions[0];d.start=DVec3::new(1.,2.,3.);d.end=DVec3::new(4.,6.,3.);d.offset=DVec3::new(-2.,0.,0.);d.axis=Some("y".into());d.layer=Some("Dimension layer".into());d.text_override=Some("Span <>".into());scene.dimensions.push(Dimension::new(DVec3::ZERO,DVec3::X,DVec3::Y));ingetrazo_formats::igz::save_igz(&scene,&dir.join("edited.igz")).unwrap();}
